// Turns the computed report into plain sentences and advice from fixed templates, written before any audit
// ran. Nothing here is generated by a language model, so the judge never interprets its own audit.
import type { JudgeReport } from "./judge-types.ts";

/** Reference points from Contra Labs, Design Crit (17 June 2026), agreement with a five-designer majority. */
export const DESIGN_CRIT = { openModels: "51–54%", trainedJudge: 0.611, designers: 0.741 } as const;

const pct = (x: number) => `${Math.round(x * 100)}%`;
const pts = (x: number) => `${x >= 0 ? "+" : "−"}${Math.abs(x).toFixed(2)}`;

export interface Findings {
  headline: string;
  lines: string[];
  advice: string[];
}

export function findings(r: JudgeReport): Findings {
  const lines: string[] = [];
  const advice: string[] = [];
  const unstable: string[] = [];

  const p = r.position;
  if (p) {
    lines.push(
      p.flipped
        ? `Swapping the order of two designs changed ${r.judge}'s choice in ${p.flipped} of ${p.pairs} pairs (${pct(p.flipRate)}). It picked the first design ${pct(p.firstShare)} of the time.`
        : `${r.judge} chose the same design in all ${p.pairs} pairs when the order was swapped.`,
    );
    if (p.flipped) {
      unstable.push(`Swap the order and ${r.judge} picks a different winner in ${pct(p.flipRate)} of pairs.`);
      advice.push("Judge every pair in both orders and accept only choices that hold in both.");
    }
  }

  const s = r.presentation;
  if (s) {
    const moved = s.interval.low > 0 || s.interval.high < 0;
    lines.push(
      moved
        ? `The same pixels in a different setting moved the average score by ${pts(s.mean)} points on a 1–5 scale (95% range ${pts(s.interval.low)} to ${pts(s.interval.high)}), although the judge was told to ignore the setting.`
        : `Presentation settings did not move the average score in a consistent direction (95% range ${pts(s.interval.low)} to ${pts(s.interval.high)}). Individual scores still moved by ${s.absMean.toFixed(2)} points on average.`,
    );
    if (moved) {
      unstable.push(`Put the same design in a different setting and its score moves by ${pts(s.mean)} points.`);
      advice.push("Show every entry to the judge in the same plain setting.");
    }
  }

  const c = r.selfConsistency;
  if (c) {
    lines.push(
      c.changeRate
        ? `Judging the same design again changed the score in ${pct(c.changeRate)} of criterion scores, by ${c.meanRange.toFixed(2)} points on average.`
        : `Judging the same design again gave identical scores every time.`,
    );
    if (c.changeRate) {
      unstable.push(`Ask again about the same design and ${r.judge} changes ${pct(c.changeRate)} of its scores.`);
      advice.push("Average at least three judgements per design instead of trusting one.");
    }
  }

  const a = r.accuracy;
  if (a) {
    lines.push(
      `${r.judge} agreed with the designer panel's majority on ${pct(a.agreement)} of ${a.n} choices` +
        (a.humanAgreement !== null ? `; individual designers agreed with the rest of the panel on ${pct(a.humanAgreement)}.` : ".") +
        ` For context, Design Crit (Contra Labs) found open models at ${DESIGN_CRIT.openModels} and designers at ${pct(DESIGN_CRIT.designers)}, on different designs.`,
    );
    if (a.agreement < DESIGN_CRIT.trainedJudge)
      advice.push(`Use ${r.judge} as a first filter only, with designers making the final call: its agreement is below the ${pct(DESIGN_CRIT.trainedJudge)} reached by a judge trained for design.`);
  }

  if (r.validCalls < r.calls)
    lines.push(`${r.calls - r.validCalls} of ${r.calls} replies could not be read and were left out.`);

  return {
    headline: unstable[0] ?? `${r.judge} held steady in this audit: no change from repeats, settings, or order.`,
    lines,
    advice: advice.slice(0, 3),
  };
}
